&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Dragon temporel adulte &lt;div style=&quot;float:right;&quot;&gt;FP 15&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Dragon&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Dragon.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Ciel&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ciel.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Extraplanaire&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Extraplanaire.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 4 page 78&lt;/i&gt;
&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;51 200 PX&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; de taille TG, N&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init&lt;/b&gt; +11 ; &lt;b&gt;Sens &lt;/b&gt;d&#233;tection de la magie, sens draconiques, vision dans les t&#233;n&#232;bres ; Perception +26&lt;/li&gt;&lt;li&gt;&lt;b&gt;Aura &lt;/b&gt;pr&#233;sence &#233;trang&#232;re (54 m, DD 23)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA &lt;/b&gt;28, contact 9, pris au d&#233;pourvu 27 (Dex +1, naturelle +19, taille -2)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv &lt;/b&gt;256 (19d12+133)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f &lt;/b&gt;+12, &lt;b&gt;Vig &lt;/b&gt;+18, &lt;b&gt;Vol &lt;/b&gt;+15&lt;/li&gt;&lt;li&gt;&lt;b&gt;RD&lt;/b&gt; 5/mage; &lt;b&gt;Immunit&#233;s &lt;/b&gt;chancelant, froid, paralysie, sommeil ; &lt;b&gt;RM &lt;/b&gt;26&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD&lt;/b&gt; 15 m, vol 60 m (m&#233;diocre)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +28 (2d8+15)&lt;ul&gt;&lt;li&gt;et 2 griffes, +28 (2d6+10/19-20)&lt;/li&gt;&lt;li&gt;et 2 ailes +25 (1d8+5)&lt;/li&gt;&lt;li&gt;et coup de queue, +25 (2d6+15)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace &lt;/b&gt;4,50 m ; &lt;b&gt;Allonge &lt;/b&gt;3 m (4,50 m avec la morsure)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque sp&#233;ciale&lt;/b&gt; &#233;crasement, souffle (c&#244;ne de 15 m, 12d10 &#233;lectricit&#233;, DD 26)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques &lt;/b&gt;(&lt;b&gt;NLS&lt;/b&gt; 19 ; concentration +23)&lt;ul&gt;&lt;li&gt;&lt;i&gt;Constant&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;&#192; volont&#233;&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Clairaudienceclairvoyance.html&quot; title=&quot;Clairaudience/clairvoyance&quot;&gt;clairaudience/clairvoyance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Partage-Des-Souvenirs.html&quot; title=&quot;Partage des souvenirs&quot;&gt;partage des souvenirs&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sorts d’ensorceleur connus&lt;/b&gt; (&lt;b&gt;NLS &lt;/b&gt;7 ; concentration +11)&lt;ul&gt;&lt;li&gt;&lt;i&gt;3&#232;me (5/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lenteur.html&quot; title=&quot;Lenteur&quot;&gt;lenteur&lt;/a&gt; (DD 17)&lt;/li&gt;&lt;li&gt;&lt;i&gt;2&#232;me (7/jour)&lt;/i&gt; —&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;D&#233;tection de pens&#233;es&quot;&gt;d&#233;tection de pens&#233;es&lt;/a&gt; (DD 16), &lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Verrou-Du-Mage.html&quot; title=&quot;Verrou du mage&quot;&gt;verrou du mage&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;1er (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Effacement.html&quot; title=&quot;Effacement&quot;&gt;effacement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Identification.html&quot; title=&quot;Identification&quot;&gt;identification&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Projectile-Magique.html&quot; title=&quot;Projectile magique&quot;&gt;projectile magique&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;0 (&#224; volont&#233;)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Message.html&quot; title=&quot;Message&quot;&gt;message&lt;/a&gt;, 3 de plus&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For&lt;/b&gt; 30, &lt;b&gt;Dex &lt;/b&gt;13, &lt;b&gt;Con&lt;/b&gt; 24, &lt;b&gt;Int &lt;/b&gt;19, &lt;b&gt;Sag &lt;/b&gt;18, &lt;b&gt;Cha &lt;/b&gt;19&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+19 ; &lt;b&gt;BMO &lt;/b&gt;+31 (+33 destruction d’arme) ; &lt;b&gt;DMD&lt;/b&gt; 44 (48 contre croc-enjambe)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (morsure, griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Encha&#238;nement.html&quot; title=&quot;Encha&#238;nement&quot;&gt;Encha&#238;nement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Savancer.html&quot; title=&quot;S&amp;#39;avancer&quot;&gt;S’avancer&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (griffe), &lt;a class=&quot;pagelink&quot; href=&quot;Succession-Dencha&#238;nements.html&quot; title=&quot;Succession d&amp;#39;encha&#238;nements&quot;&gt;Succession d’encha&#238;nements&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Connaissances (histoire))&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +26, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (histoire) +32, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res, g&#233;ographie, plans, religion) +26, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +26, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +26, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +26, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +15&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues &lt;/b&gt;commun, draconique, elfe, nain, sylvestre&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s &lt;/b&gt;immortel, lire les fils, ne respire pas, vol stellaire&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Sid&#233;ral.html&quot; title=&quot;Les dragons sid&#233;raux&quot;&gt;dragons sid&#233;raux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Temporel.html&quot; title=&quot;Dragon sid&#233;ral temporel&quot;&gt;dragons temporels&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Les &#233;cailles fissur&#233;es de ce dragon cr&#233;pitent sous l’effet d’un pouvoir aussi patient que terrifiant. Certaines de ses cornes sont vieilles et fragiles tandis que d’autres sont neuves et immacul&#233;es.&lt;/i&gt;  &lt;br /&gt;&lt;br /&gt;Gardiens de l’Histoire, les dragons temporels sont les plus puissants de tous les dragons sid&#233;raux. Ils veillent et attendent, prot&#233;geant l’univers contre tous ceux qui voudraient modifier l’ordre
temporel.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
